import { Show } from 'solid-js';
import type { JSX } from 'solid-js';
import { text } from '../../stores/view.js';
import './edit.css';

export const DRAG_HANDLE = 'drag-handle';
export const DROP_TARGET = 'drop-doel';
export const DROP_TARGET_ACTIVE = 'drop-doel-actief';
export const DRAGGING_CONSTRAINT = 'sleept-voorwaarde';

export function DragGhost(props: {
  name?: string;
  hint?: string;
  x: number;
  y: number;
}): JSX.Element {
  return (
    <div
      class="sleep-spook"
      style={{ left: `${(Number(props.x) || 0) + 12}px`, top: `${(Number(props.y) || 0) + 12}px` }}
    >
      <span>{props.name || text('edit.dragUnnamed')}</span>
      <Show when={props.hint !== ''}>
        <span class="sleep-hint">{props.hint ?? text('edit.dropCopy')}</span>
      </Show>
    </div>
  );
}

export function ActionDropZone(props: {
  extraCls?: string;
  ref?: (el: HTMLElement) => void;
} = {}): JSX.Element {
  return (
    <span
      ref={(el: HTMLElement) => props.ref?.(el)}
      class={['actie-drop-zone', props.extraCls || ''].filter(Boolean).join(' ')}
      title={text('edit.actionDropZone')}
    >{`↳ ${text('field.action')}`}</span>
  );
}
