import { Show, createEffect, createSignal, on, onCleanup } from 'solid-js';
import type { JSX } from 'solid-js';
import { text } from '../../stores/view.js';
import { core } from './core.js';
import './edit.css';

export const TOAST_MS = 6000;

const [notice, setNotice] = createSignal<{ key: string; token: number } | null>(null);
let counter = 0;

export { notice as toastNotice };

export function showToast(key: string): void {
  if (!key) return;
  counter += 1;
  setNotice({ key, token: counter });
}

export function clearToast(): void { setNotice(null); }

export function Toast(): JSX.Element {
  let tick: ReturnType<typeof setTimeout> | null = null;
  const stop = () => { if (tick) { clearTimeout(tick); tick = null; } };
  onCleanup(stop);
  // The timer belongs in an effect: the function child of `<Show>` runs once
  // while its condition holds, so a second notice would inherit the first clock.
  createEffect(on(notice, (m) => {
    stop();
    if (!m) return;
    tick = setTimeout(() => { tick = null; clearToast(); }, TOAST_MS);
  }));
  return (
    <Show when={notice()}>{(m) => (
        <div class="bewerk-toast" role="status" aria-live="polite">
          <span class="bewerk-toast-tekst">{text(m().key)}</span>
          <button
            type="button"
            class="bewerk-toast-undo"
            on:click={(e: MouseEvent) => {
              e.preventDefault();
              e.stopPropagation();
              clearToast();
              void core().undo();
            }}
          >{text('edit.undo')}</button>
          <button
            type="button"
            class="bewerk-toast-sluit"
            title={text('edit.closeToast')}
            aria-label={text('edit.closeToast')}
            on:click={(e: MouseEvent) => { e.preventDefault(); e.stopPropagation(); clearToast(); }}
          >×</button>
        </div>
    )}</Show>
  );
}
