import type { JSX } from 'solid-js';
import { setCardHooks } from './hooks.jsx';
import type { FieldSpec } from './hooks.jsx';
import { attachCore } from './core.js';
import { attachIntegration } from './integration/mount.js';
import { CardField } from './card-field.jsx';
import { Chrome } from './chrome.jsx';

export interface LoadedLayer {
  Chrome: () => JSX.Element;
  setEditMode: (on: boolean, options?: { bevestig?: boolean }) => boolean;
  confirmEditMode: (options?: { stil?: boolean }) => void;
}

let loaded: LoadedLayer | null = null;

export async function load(): Promise<LoadedLayer> {
  if (loaded) return loaded;
  const k = await attachCore();
  setCardHooks({
    field: (spec: FieldSpec, read: () => JSX.Element) => CardField({ spec, read }),
  });
  await attachIntegration();
  loaded = {
    Chrome,
    setEditMode: k.setEditMode,
    confirmEditMode: k.confirmEditMode,
  };
  return loaded;
}

export function _detachForTest(): void {
  loaded = null;
  setCardHooks(null);
}
