import { Show, createMemo, onCleanup } from 'solid-js';
import type { JSX } from 'solid-js';
import type { Term } from '../../../model-boundary.js';
import { model } from '../../../stores/corpus.js';
import { termOf } from '../integration/anchor.js';
import { text } from '../../../stores/view.js';
import { ownConstraints } from '../../card/fill.jsx';
import type { CoverageRule } from '../../card/fill.jsx';
import './drag.css';

export const SHARED_HL = 'is-ref-hl';

export interface SharedCard { iri: string; title: string }

interface NodeShort { term?: Term | null }
interface ConstraintShort extends NodeShort { children?: ConstraintShort[] }
interface RuleShort extends NodeShort {
  constraints?: ConstraintShort[];
  refinements?: ConstraintShort[];
  purposeConstraint?: ConstraintShort | null;
  duties?: RuleShort[];
  consequences?: RuleShort[];
}
interface PolicyShort extends NodeShort {
  iri?: string;
  title?: string | null;
  permissions?: RuleShort[];
  prohibitions?: RuleShort[];
  obligations?: RuleShort[];
}
interface ModelShort {
  sets?: PolicyShort[]; offers?: PolicyShort[]; agreements?: PolicyShort[];
}

// Reading `.value` off a model term works in jsdom and gives '' in the browser,
// after which the marker silently never appears.
const keyOf = (term: Term | string | null | undefined): string =>
  termOf(term)?.value || '';

const constraintsOf = (rule: RuleShort): ConstraintShort[] =>
  ownConstraints(rule as unknown as CoverageRule) as unknown as ConstraintShort[];

function inConstraint(c: ConstraintShort, key: string, seen: Set<unknown>): boolean {
  if (keyOf(c.term) === key) return true;
  if (seen.has(c)) return false;
  seen.add(c);
  for (const child of c.children || []) if (inConstraint(child, key, seen)) return true;
  return false;
}

function inRule(rule: RuleShort, key: string, seen: Set<unknown>): boolean {
  if (keyOf(rule.term) === key) return true;
  if (seen.has(rule)) return false;
  seen.add(rule);
  for (const c of constraintsOf(rule)) if (inConstraint(c, key, seen)) return true;
  for (const d of rule.duties || []) if (inRule(d, key, seen)) return true;
  for (const d of rule.consequences || []) if (inRule(d, key, seen)) return true;
  return false;
}

function inCard(pol: PolicyShort, key: string): boolean {
  if (keyOf(pol.term) === key) return true;
  const seen = new Set<unknown>();
  for (const group of [pol.permissions, pol.prohibitions, pol.obligations]) {
    for (const r of group || []) if (inRule(r, key, seen)) return true;
  }
  return false;
}

export function cardsOfNode(m: unknown, term: Term | string | null): SharedCard[] {
  const key = keyOf(term);
  if (!m || !key) return [];
  const mm = m as ModelShort;
  const out: SharedCard[] = [];
  const seen = new Set<string>();
  for (const pol of [...(mm.sets || []), ...(mm.offers || []), ...(mm.agreements || [])]) {
    const iri = pol.iri || keyOf(pol.term);
    if (!iri || seen.has(iri)) continue;
    if (!inCard(pol, key)) continue;
    seen.add(iri);
    out.push({ iri, title: pol.title || iri });
  }
  return out;
}

const CARD_SELECTOR = (safeIri: string): string => `details[data-ref="${safeIri}"]`;

let highlighted: HTMLElement[] = [];

function unlight(): void {
  for (const n of highlighted) n.classList?.remove(SHARED_HL);
  highlighted = [];
}

function light(iris: string[]): void {
  unlight();
  if (typeof document === 'undefined') return;
  for (const iri of iris) {
    const safe = iri.replace(/["\\]/g, '\\$&');
    for (const n of document.querySelectorAll<HTMLElement>(CARD_SELECTOR(safe))) {
      n.classList.add(SHARED_HL);
      highlighted.push(n);
    }
  }
}

export function SharedMarker(props: {
  term: Term | string | null;
  card?: string | null;
}): JSX.Element {
  const cards = createMemo(() => cardsOfNode(model(), props.term));
  const others = () => cards().map((k) => k.iri).filter((iri) => iri !== props.card);
  onCleanup(unlight);
  return (
    <Show when={cards().length > 1}>
      <span
        class="gedeeld-merk"
        title={text('edit.sharedHint', { n: cards().length })}
        on:mouseenter={() => light(others())}
        on:mouseleave={unlight}
      >
        {text('edit.sharedCount', { n: cards().length })}
      </span>
    </Show>
  );
}
