import { Show, createEffect, createSignal, onCleanup } from 'solid-js';
import type { JSX } from 'solid-js';
import { sourcesOpen, setSourcesOpen } from '../app/sources.jsx';
import { setSourceChoice } from './hooks.jsx';
import { text, view } from '../../stores/view.js';
import { Editbar, Button } from './button.jsx';
import { core } from './core.js';
import { DragLayer } from './drag/drag-layer.jsx';
import { Toast } from './toast.jsx';
import './edit.css';

function attachKeys(): () => void {
  if (typeof document === 'undefined' || !document.addEventListener) return () => {};
  const onKey = (e: KeyboardEvent) => {
    if (!view.editMode) return;
    if (!(e.ctrlKey || e.metaKey) || e.altKey) return;
    const a = document.activeElement as (HTMLElement | null);
    const tag = a && a.tagName ? String(a.tagName).toLowerCase() : '';
    if (tag === 'input' || tag === 'textarea' || (a && a.isContentEditable)) return;
    const k = String(e.key || '').toLowerCase();
    let action: (() => Promise<boolean>) | null = null;
    if (k === 'z') action = e.shiftKey ? core().redo : core().undo;
    else if (k === 'y' && !e.shiftKey) action = core().redo;
    if (!action) return;
    e.preventDefault();
    void action();
  };
  document.addEventListener('keydown', onKey);
  return () => document.removeEventListener('keydown', onKey);
}

function Offer(): JSX.Element {
  return (
    <div class="bewerk-aanbod" role="status">
      <span class="bewerk-aanbod-uitleg">{text('edit.noWriteSource')}</span>
      {' '}
      <Editbar>
        <Button
          label={text('edit.chooseEditSource')}
          cls="bewerk-aanbod-kies"
          onClick={() => { if (!sourcesOpen()) setSourcesOpen(true); }}
        />
        <Button
          label={text('edit.cancel')}
          cls="bewerk-aanbod-sluit"
          onClick={() => core().closeOffer()}
        />
      </Editbar>
    </div>
  );
}

export function Chrome(): JSX.Element {
  const [busy, setBusy] = createSignal(false);
  onCleanup(attachKeys());

  createEffect(() => setSourceChoice(core().offerOpen()));
  onCleanup(() => setSourceChoice(false));

  const save = () => {
    setBusy(true);
    void core().flushSource().finally(() => setBusy(false));
  };

  return (
    <Show when={view.editMode || core().offerOpen()}>
      <div class="bewerk-balk" id="bewerk-balk">
        <Show when={view.editMode}>
          <Editbar>
            <button
              type="button"
              class={core().canUndo() ? 'edit-knop bewerk-undo' : 'edit-knop bewerk-undo actie-uit'}
              title={text('edit.undo')}
              aria-label={text('edit.undo')}
              aria-disabled={core().canUndo() ? undefined : 'true'}
              on:click={(e: MouseEvent) => {
                e.preventDefault();
                e.stopPropagation();
                if (core().canUndo()) void core().undo();
              }}
            >↶</button>
            <button
              type="button"
              class={core().canRedo() ? 'edit-knop bewerk-redo' : 'edit-knop bewerk-redo actie-uit'}
              title={text('edit.redo')}
              aria-label={text('edit.redo')}
              aria-disabled={core().canRedo() ? undefined : 'true'}
              on:click={(e: MouseEvent) => {
                e.preventDefault();
                e.stopPropagation();
                if (core().canRedo()) void core().redo();
              }}
            >↷</button>
            <Button
              label={text('edit.saveNow')}
              cls="bewerk-bewaar"
              title={text('edit.saveNowHint')}
              onClick={save}
            />
          </Editbar>
          <Show when={busy()}>
            <span class="bewerk-bezig muted" role="status">{text('edit.saving')}</span>
          </Show>
          <Show when={core().editSource()}>{(b) => (
            <span class="bewerk-bron muted">
              {text('edit.writeSource')}{' '}
              <span class="bewerk-bron-naam">{b().name || b().url || b().graph}</span>
            </span>
          )}</Show>
        </Show>
        <Show when={core().offerOpen()}><Offer /></Show>
        <Show when={view.editMode}><DragLayer /></Show>
        <Show when={view.editMode}><Toast /></Show>
      </div>
    </Show>
  );
}
