import type { JSX } from 'solid-js';
import { text } from '../../../stores/view.js';
import { IriCombobox } from '../field.jsx';
import type { IriOption } from '../field.jsx';
import { Button } from '../button.jsx';
import type { GhostOption } from '../ghost.jsx';
import { editState } from './state.jsx';
import type { Core } from './core.js';
import type { Term } from '../../../model-boundary.js';

export const REUSE_LABEL = (): string => `↻ ${text('edit.reuse')}`;

export const RULE_NOTICE: Record<string, string> = {
  onbekend: 'edit.reuseUnknown',
  wrongKind: 'edit.reuseKind',
  alreadyLinked: 'edit.reuseAlready',
};

export const CONSTRAINT_NOTICE: Record<string, string> = {
  onbekend: 'edit.reuseConstraintUnknown',
  wrongKind: 'edit.reuseConstraintKind',
  alreadyLinked: 'edit.reuseConstraintAlready',
};

export function reuseSegment(opts: {
  core: Core;
  term: Term | null;
  cls: string;
  count: number;
  hint: string;
  none: string;
  toggle: () => void;
}): GhostOption {
  const label = REUSE_LABEL();
  const cls = `${opts.cls} ghost-hergebruik`;
  if (!opts.count) {
    return { label, cls, title: text(opts.none), on: false };
  }
  const state = editState(opts.core, {
    allow: opts.core.editable(opts.term),
    title: text(opts.hint),
    action: opts.toggle,
    term: opts.term,
    unlockable: true,
  });
  return { label, cls, title: state.title, on: state.on, action: state.action };
}

export function ReuseRow(props: {
  options: IriOption[];
  chooseKey: string;
  onPick: (iri: string) => void;
  onClose: () => void;
  cls?: string;
}): JSX.Element {
  return (
    <div class={['hergebruik-rij', props.cls || ''].filter(Boolean).join(' ')}>
      <IriCombobox
        options={props.options}
        ariaLabel={text(props.chooseKey)}
        placeholder={text(props.chooseKey)}
        onPick={(iri: string) => { if (iri) props.onPick(iri); }}
      />
      <Button
        label={text('edit.cancel')}
        cls="hergebruik-annuleer"
        onClick={props.onClose}
      />
    </div>
  );
}

export function asIriOptions(list: {
  iri: string; curie: string | null; label: string; provenance: string[];
}[]): IriOption[] {
  return list.map((r) => ({
    iri: r.iri,
    label: r.label,
    curie: r.curie || undefined,
    extra: r.provenance.length
      ? text('edit.reuseOrigin', { beleid: r.provenance.join(', ') }) : undefined,
  }));
}
