import { createSignal, onCleanup } from 'solid-js';
import {
  DROPTARGET as DROPTARGET_JS, DRAGITEM as DRAGITEM_JS,
  validDropTargets as validDropTargetsJs, linkAttached as linkAttachedJs,
  moveAttached as moveAttachedJs, termKey as termKeyJs,
  moveConstraint as moveConstraintJs,
} from '../../../model/edit.js';
import type { Term } from '../../../model-boundary.js';
import { graphVersion, model } from '../../../stores/corpus.js';
import { editable, editSource, execute } from '../../../stores/edit.js';
import type { WriteStore } from '../../../stores/edit.js';
import { text } from '../../../stores/view.js';
import { termOf } from '../integration/anchor.js';
import { DROP_TARGET, DROP_TARGET_ACTIVE } from '../drag.jsx';
import { actionState } from '../strip.jsx';
import type { IconState } from '../strip.jsx';

// `validDropTargets` in `model/edit.js` reads `kind`/`parent`/`pred` and writes
// `{ kind, term, pred }` across an untyped cast: renaming a field here without
// that file fails silently (empty target list, handle always off).
export const DROPTARGET = DROPTARGET_JS as { CARD: string; RULE: string; ACTION: string };
export const DRAGITEM = DRAGITEM_JS as { NODE: string; CONSTRAINT: string };

export interface DragItem {
  kind: string;
  term: Term;
  parent?: Term | null;
  pred?: string;
  label?: string;
}

export interface DragTarget { kind: string; term: Term; pred: string }

type Allow = (term: Term, kind: string, pred: string) => boolean;

const validDropTargets = validDropTargetsJs as unknown as
  (m: unknown, item: DragItem, opts?: { allow?: Allow }) => DragTarget[];
const termKey = termKeyJs as unknown as (term: Term | null | undefined) => string;
const moveAttached = moveAttachedJs as unknown as (store: WriteStore, fromParent: unknown,
  fromPred: unknown, term: unknown, toParent: unknown, toPred: unknown) => void;
const linkAttached = linkAttachedJs as unknown as
  (store: WriteStore, toParent: unknown, toPred: unknown, term: unknown) => void;
const moveConstraint = moveConstraintJs as unknown as (store: WriteStore,
  from: { parent: unknown; pred: string }, cTerm: unknown,
  to: { parent: unknown; pred: string }, opts?: { copy?: boolean }) => void;

interface Zone { node: HTMLElement; kind: string; term: Term }
let zones: Zone[] = [];

const zoneKey = (kind: string, term: Term): string => `${kind}|${termKey(term)}`;

export const bodyClass = (kind: string): string => `sleept-${kind}`;

export function reportDropZone(node: HTMLElement, kind: string, term: Term): () => void {
  if (!node || !term || typeof node.addEventListener !== 'function') return () => {};
  const zone: Zone = { node, kind, term };
  zones.push(zone);
  const enter = (): void => {
    if (!state) return;
    const pred = state.targets.get(zoneKey(kind, term));
    if (pred === undefined) return;
    setHover([...hover(), { kind, term, pred }]);
    node.classList.add(DROP_TARGET_ACTIVE);
  };
  const leave = (): void => {
    if (!state) return;
    setHover(hover().filter((d) => termKey(d.term) !== termKey(term) || d.kind !== kind));
    node.classList.remove(DROP_TARGET_ACTIVE);
  };
  node.addEventListener('pointerenter', enter);
  node.addEventListener('pointerleave', leave);
  return () => {
    node.removeEventListener('pointerenter', enter);
    node.removeEventListener('pointerleave', leave);
    node.classList.remove(DROP_TARGET, DROP_TARGET_ACTIVE);
    zones = zones.filter((z) => z !== zone);
  };
}

export function dropTarget(node: HTMLElement | null, kind: string, term: Term | null): void {
  if (!node || !term) return;
  const off = reportDropZone(node, kind, term);
  onCleanup(off);
}

interface State {
  item: DragItem;
  targets: Map<string, string>;
  pointerId: number | undefined;
}

let state: State | null = null;
const [dragItem, setDragItem] = createSignal<DragItem | null>(null);
const [dragPosition, setPosition] = createSignal<{ x: number; y: number }>({ x: 0, y: 0 });
const [hover, setHover] = createSignal<DragTarget[]>([]);

export { dragItem, dragPosition };

export function currentTarget(): DragTarget | null {
  const h = hover();
  return h.length ? h[h.length - 1] : null;
}

const mayDrop: Allow = (term) => mayEdit(term);

let cacheStamp = '';
let cacheModel: unknown = null;
const targetCache = new Map<string, DragTarget[]>();
const mayCache = new Map<string, boolean>();

const keyOfTerm = (t: Term | string | null | undefined): string =>
  (typeof t === 'string' ? t : termKey(t as Term));

// The model arrives by structured clone, so its terms carry only `id`; passing
// one on makes N3 throw and takes the card's rendering with it. jsdom does not
// catch this — there the model is built in the same thread.
const realTerm = (t: Term | null | undefined): Term | null => termOf(t);

function freshGeneration(m: unknown): void {
  const source = editSource();
  const stamp = `${graphVersion()}|${source ? source.graph : ''}`;
  if (stamp === cacheStamp && m === cacheModel) return;
  cacheStamp = stamp;
  cacheModel = m;
  targetCache.clear();
  mayCache.clear();
}

function mayEdit(term: Term | string | null | undefined): boolean {
  freshGeneration(model());
  const k = keyOfTerm(term);
  let v = mayCache.get(k);
  if (v === undefined) {
    v = editable(typeof term === 'string' ? term : realTerm(term));
    mayCache.set(k, v);
  }
  return v;
}

export function validTargets(item: DragItem): DragTarget[] {
  const m = model();
  if (!m || !item || !item.term) return [];
  freshGeneration(m);
  const k = `${item.kind}|${keyOfTerm(item.term)}|${keyOfTerm(item.parent)}|${item.pred || ''}`;
  const known = targetCache.get(k);
  if (known) return known;
  const targets = validDropTargets(m, item, { allow: mayDrop })
    .map((d) => ({ ...d, term: realTerm(d.term) || d.term }));
  targetCache.set(k, targets);
  return targets;
}

function otherFinger(e: { pointerId?: number } | null): boolean {
  return !!state && state.pointerId !== undefined && !!e && e.pointerId !== undefined
    && e.pointerId !== state.pointerId;
}

type Gesture = MouseEvent & { pointerId?: number };

export function startDrag(e: Gesture, item: DragItem): boolean {
  if (e && e.button) return false;
  if (state) cancelDrag();
  if (!item || !item.term) return false;
  const targets = validTargets(item);
  if (!targets.length) return false;
  if (e && typeof e.preventDefault === 'function') e.preventDefault();
  releaseImplicitCapture(e);
  state = {
    item,
    targets: new Map(targets.map((d) => [zoneKey(d.kind, d.term), d.pred])),
    pointerId: e ? e.pointerId : undefined,
  };
  setDragItem(() => item);
  setHover([]);
  setPosition({ x: e ? e.clientX : 0, y: e ? e.clientY : 0 });
  for (const z of zones) {
    if (state.targets.has(zoneKey(z.kind, z.term))) z.node.classList.add(DROP_TARGET);
  }
  document.body?.classList.add(bodyClass(item.kind));
  return true;
}

function releaseImplicitCapture(e: Gesture): void {
  const handle = (e && (e.currentTarget || e.target)) as HTMLElement | null;
  if (!handle || e.pointerId === undefined) return;
  if (typeof handle.releasePointerCapture !== 'function'
    || typeof handle.hasPointerCapture !== 'function') return;
  if (handle.hasPointerCapture(e.pointerId)) handle.releasePointerCapture(e.pointerId);
}

function cleanUp(): void {
  if (!state) return;
  for (const z of zones) z.node.classList.remove(DROP_TARGET, DROP_TARGET_ACTIVE);
  document.body?.classList.remove(bodyClass(state.item.kind));
  state = null;
  setDragItem(null);
  setHover([]);
}

export function cancelDrag(): void {
  cleanUp();
}

function runDrop(item: DragItem, target: DragTarget, alt: boolean): Promise<boolean> {
  if (item.kind === DRAGITEM.CONSTRAINT) {
    const from = { parent: item.parent, pred: item.pred as string };
    const to = { parent: target.term, pred: target.pred };
    return execute((f) => moveConstraint(f, from, item.term, to, alt ? { copy: true } : {}),
      { group: true });
  }
  if (alt) {
    return execute((f) => linkAttached(f, target.term, target.pred, item.term), { group: true });
  }
  return execute(
    (f) => moveAttached(f, item.parent, item.pred, item.term, target.term, target.pred),
    { group: true },
  );
}

function move(e: Gesture): void {
  if (!state || otherFinger(e)) return;
  setPosition({ x: e.clientX, y: e.clientY });
}

function end(e: Gesture): void {
  if (!state || otherFinger(e)) return;
  const { item } = state;
  const target = currentTarget();
  const alt = !!(e && e.altKey);
  cleanUp();
  if (target) void runDrop(item, target, alt);
}

function cancelFromPointer(e: Gesture): void {
  if (!state || otherFinger(e)) return;
  cancelDrag();
}

/** On the WINDOW and not the document: the fill panel hangs in the capture
 *  phase on the document and is registered first, so an Escape during a drag
 *  would close the panel instead of aborting the gesture. */
export function attachDragLayers(): () => void {
  if (typeof window === 'undefined' || !window.addEventListener) return () => {};
  const onKey = (e: KeyboardEvent): void => {
    if (e.key !== 'Escape' || !state) return;
    e.preventDefault();
    if (e.stopImmediatePropagation) e.stopImmediatePropagation();
    else e.stopPropagation();
    cancelDrag();
  };
  window.addEventListener('pointermove', move as EventListener);
  window.addEventListener('pointerup', end as EventListener);
  window.addEventListener('pointercancel', cancelFromPointer as EventListener);
  window.addEventListener('keydown', onKey, true);
  return () => {
    window.removeEventListener('pointermove', move as EventListener);
    window.removeEventListener('pointerup', end as EventListener);
    window.removeEventListener('pointercancel', cancelFromPointer as EventListener);
    window.removeEventListener('keydown', onKey, true);
    cancelDrag();
  };
}

export type Draggability = 'canDrag' | 'noAttachment' | 'locked' | 'noTarget';

export function draggability(item: DragItem): Draggability {
  if (!item || !item.term || !item.parent || !item.pred) return 'noAttachment';
  if (!mayEdit(item.parent)) return 'locked';
  if (!validTargets(item).length) return 'noTarget';
  return 'canDrag';
}

export function canDrag(item: DragItem): boolean {
  return draggability(item) === 'canDrag';
}

const REASON: Record<Exclude<Draggability, 'canDrag'>, string> = {
  noAttachment: 'edit.dragNoLink',
  locked: 'edit.dragLocked',
  noTarget: 'edit.dragNoTarget',
};

export function dragHandle(item: DragItem, title?: string): IconState {
  const explanation = title || text('edit.dragHandle');
  const state = draggability(item);
  if (state !== 'canDrag') {
    return actionState({ allow: false, title: explanation, notApplicable: text(REASON[state]) });
  }
  return {
    on: true, title: explanation, opPointerDown: (e) => { startDrag(e as Gesture, item); },
  };
}
