import { For, Show, createMemo, createSignal, onMount } from 'solid-js';
import type { JSX } from 'solid-js';
import { expandIri } from '../../../model/edit.js';
import { curie } from '../../../model/parse.js';
import { validIriText } from '../../../model/fields.js';
import { text, setNotice } from '../../../stores/view.js';
import type { Term } from '../../../model-boundary.js';
import { fieldOptions } from '../card-field.jsx';
import { filterSuggestions, focusWithoutJump, IriCombobox, optionText } from '../field.jsx';
import type { FieldHook } from '../field.jsx';
import { ODRL } from './anchor.js';
import { Editbar, Button } from '../button.jsx';
import { SLOT_DATATYPES, compoundValue, slotValues } from './slots.js';
import type { Core } from './core.js';
import './slot-editor.css';

interface Right {
  value: string; kind: 'iri' | 'literal'; lang?: string; datatype?: string;
}

function SlotCombobox(props: {
  category: string; current: string; label: string; hint: string;
  hook: (api: FieldHook & { value: () => string }) => void;
}): JSX.Element {
  const options = createMemo(() => fieldOptions(props.category));
  return (
    <span class="c-editor-slot">
      <IriCombobox
        options={options()}
        value={optionText(options(), props.current) || props.current}
        ariaLabel={props.label}
        placeholder={props.hint}
        hook={props.hook}
      />
    </span>
  );
}

function langDatatypeOptions(right: { lang: string; datatype: string }): [string, string][] {
  const options: [string, string][] = [
    ['', text('edit.noLangDatatype')], ['lang:nl', '@nl'], ['lang:en', '@en'],
    ...SLOT_DATATYPES.map((d) => [d, (curie(d) as string) || d] as [string, string]),
  ];
  const current = right.lang ? `lang:${right.lang}` : (right.datatype || '');
  if (current && !options.some(([v]) => v === current)) {
    options.push([current, right.lang ? `@${right.lang}`
      : ((curie(right.datatype) as string) || current)]);
  }
  return options;
}

function valueCategory(left: string): string {
  return left === `${ODRL}purpose` ? 'purposes' : 'labeled';
}

let valueListCounter = 0;

export function SlotEditor(props: {
  core: Core;
  term: Term;
  c: { slots?: { right?: { texts?: string[] } | null } | null } | null;
  onClose: () => void;
  focus?: 'left' | 'value' | null;
  onOpened?: () => void;
}): JSX.Element {
  const store = () => props.core.graph();
  const w = createMemo(() => slotValues(store(), props.term, curie as (i: string) => string | null));
  const fixed = createMemo(() => compoundValue(store(), props.term));
  const shared = () => props.term.termType === 'NamedNode';

  let leftHook: (FieldHook & { value: () => string }) | null = null;
  let opHook: (FieldHook & { value: () => string }) | null = null;
  let valueEl!: HTMLInputElement;
  let kindEl!: HTMLSelectElement;
  let dtEl!: HTMLSelectElement;

  const chipText = () => (props.c?.slots?.right?.texts || []).join(', ');
  const [kind, setKind] = createSignal<'literal' | 'iri'>(w().right.kind);

  const [typedValue, setTypedValue] = createSignal('');
  const valueOptions = createMemo(() => (kind() === 'iri'
    ? filterSuggestions(fieldOptions(valueCategory(w().left)), typedValue())
    : []));
  valueListCounter += 1;
  const valueListId = `slot-waarde-dl-${valueListCounter}`;

  onMount(() => {
    kindEl.value = w().right.kind;
    dtEl.value = w().right.lang ? `lang:${w().right.lang}` : (w().right.datatype || '');
    if (props.focus === 'left') leftHook?.openEdit();
    else if (props.focus === 'value') focusWithoutJump(valueEl);
    props.onOpened?.();
  });

  const save = (): void => {
    const left = leftHook ? leftHook.value() : '';
    const operator = opHook ? opHook.value() : '';
    for (const iri of [left, operator]) {
      if (iri && !validIriText(iri)) {
        setNotice('edit.invalidIri', { invoer: iri });
        return;
      }
    }
    let right: Right | undefined;
    if (!fixed()) {
      if (kindEl.value === 'iri') {
        const iri = expandIri(String(valueEl.value || '').trim()) as string;
        if (iri && !validIriText(iri)) {
          setNotice('edit.invalidIri', { invoer: valueEl.value });
          return;
        }
        right = { value: iri, kind: 'iri' };
      } else {
        const choice = String(dtEl.value || '');
        right = {
          value: valueEl.value,
          kind: 'literal',
          lang: choice.startsWith('lang:') ? choice.slice(5) : undefined,
          datatype: choice && !choice.startsWith('lang:') ? choice : undefined,
        };
      }
    }
    void props.core.execute(
      (f) => props.core.edit.setConstraint(f, props.term, { left, operator, right }),
      { group: true },
    ).then((ok) => { if (ok) props.onClose(); }).catch(() => {});
  };

  return (
    <div class="c-editor">
      <Show when={shared()}>
        <p class="c-editor-waarschuwing">
          {text('edit.sharedBuildingBlock', {
            term: (curie(props.term.value) as string) || props.term.value,
          })}
        </p>
      </Show>
      <div class="c-editor-form">
        <label class="c-editor-label">{text('edit.slotLeft')}</label>
        <SlotCombobox
          category="leftOperands" current={w().left} label={text('edit.slotLeft')}
          hint={text('edit.hintQuantity')}
          hook={(api) => { leftHook = api; }}
        />
        <label class="c-editor-label">{text('edit.slotOperator')}</label>
        <SlotCombobox
          category="operators" current={w().operator} label={text('edit.slotOperator')}
          hint={text('edit.hintOperator')}
          hook={(api) => { opHook = api; }}
        />
        <label class="c-editor-label">{text('edit.slotKind')}</label>
        <select
          ref={(n) => { kindEl = n; }}
          class="edit-input c-editor-soort"
          aria-label={text('edit.slotKind')}
          disabled={fixed()}
          on:change={(e) => setKind((e.currentTarget as HTMLSelectElement).value as 'iri')}
        >
          <option value="literal">{text('edit.valueLiteral')}</option>
          <option value="iri">{text('edit.valueIri')}</option>
        </select>
        <label class="c-editor-label">{text('edit.slotValue')}</label>
        <input
          ref={(n) => { valueEl = n; }}
          type="text"
          class="edit-input c-editor-waarde"
          aria-label={text('edit.slotValue')}
          placeholder={fixed() ? undefined : text('edit.hintValue')}
          disabled={fixed()}
          list={valueListId}
          on:input={(e) => setTypedValue((e.currentTarget as HTMLInputElement).value)}
          value={fixed() ? chipText() : w().right.value}
          on:keydown={(e: KeyboardEvent) => {
            if (e.key === 'Enter') { e.preventDefault(); e.stopPropagation(); save(); }
            if (e.key === 'Escape') { e.preventDefault(); e.stopPropagation(); props.onClose(); }
          }}
        />
        <datalist id={valueListId}>
          <For each={valueOptions()}>{(o) => (
            <option value={o.curie || o.iri} label={o.label !== o.curie ? o.label : undefined} />
          )}</For>
        </datalist>
        <label class="c-editor-label">{text('edit.slotLangDatatype')}</label>
        <select
          ref={(n) => { dtEl = n; }}
          class="edit-input c-editor-dt"
          aria-label={text('edit.slotLangDatatype')}
          disabled={fixed() || kind() === 'iri'}
        >
          <For each={langDatatypeOptions(w().right)}>{([v, label]) => (
            <option value={v}>{label}</option>
          )}</For>
        </select>
      </div>
      <Show when={fixed()}>
        <p class="c-editor-vast muted">{text('edit.valueFixed')}</p>
      </Show>
      <Editbar>
        <Button label={text('edit.save')} cls="c-editor-opslaan" onClick={save} />
        <Button label={text('edit.cancel')} cls="c-editor-annuleren" onClick={props.onClose} />
      </Editbar>
    </div>
  );
}
