const DUTY = `${ODRL}duty`;
const PURPOSE_LEFT = `${ODRL}purpose`;

type ConstraintShape = {
  purposeBinding?: boolean;
  technicalMeasure?: boolean;
  logical?: string | null;
  children?: unknown[];
  slots?: { right?: { texts?: string[] } | null } | null;
  label?: string | null;
};

const noHandle = (reason: string): IconState => ({ on: false, title: reason });

function DerivedStrip(props: {
  reason: string; edit?: IconState; duplicate?: boolean;
}): JSX.Element {
  const off = (): IconState => ({ on: false, title: props.reason });
  return (
    <ActionStrip
      drag={off()}
      edit={props.edit}
      duplicate={props.duplicate ? off() : undefined}
      remove={off()}
    />
  );
}

export function RuleStrip(props: { core: Core; ctx: RuleHookCtx }): JSX.Element {
  const term = createMemo(() => (props.ctx.derived ? null : termOf(props.ctx.rule)));
  const anchor = createMemo<Anchor | null>(() => nodeAnchor(
    props.core.graph(), term(), NODE_PREDS, props.ctx.parent,
  ));
  const stillUsed = () => staysInUse(props.core.graph(), anchor(), term());
  const detachedQuads = createMemo(() => detachQuads(
    props.core.graph(), anchor(), term(),
    (s, t) => props.core.edit.closureQuads(s, t),
  ));
  const canDetach = () => detachedQuads().length > 0
    && props.core.quadsInEditSource(detachedQuads());
  const dragItem = createMemo<DragItem | null>(() => {
    const t0 = term(); const a = anchor();
    if (!t0) return null;
    return {
      kind: DRAGITEM.NODE,
      term: t0,
      parent: a ? a.parent : null,
      pred: a ? a.pred : undefined,
      label: (props.ctx.rule as { title?: string | null }).title || undefined,
    };
  });
  return (
    <Show
      when={term()}
      fallback={(
        <DerivedStrip
          reason={text('edit.rowDerived')}
          edit={props.ctx.titleEdit as IconState | undefined}
          duplicate
        />
      )}
    >
      {(t0) => (
        <ActionStrip
          label={text('edit.stripLabel')}
          ref={(el) => zoneOnHeader(el, '.op-summary', DROPTARGET.RULE, t0())}
          voor={(
            <>
              <SharedMarker term={t0()} card={props.ctx.scope ?? null} />
              <ActionDropZone
                ref={(el) => zoneOnHeader(el, '.actie-drop-zone', DROPTARGET.ACTION, t0())}
              />
            </>
          )}
          drag={dragItem()
            ? dragHandle(dragItem()!)
            : noHandle(text('edit.dragNoLink'))}
          edit={props.ctx.titleEdit as IconState | undefined}
          duplicate={anchor()
            ? editState(props.core, {
              allow: props.core.editable(t0()),
              title: text('edit.duplicateHint'),
              action: () => {
                const a = anchor()!;
                void props.core.execute(
                  (f) => props.core.edit.duplicateAttached(f, a.parent, a.pred, t0()),
                  { group: true },
                );
              },
              term: t0(),
              unlockable: true,
            })
            : { on: false, title: text('edit.duplicateNoLink') }}
          remove={editState(props.core, {
            allow: canDetach(),
            title: text(stillUsed() ? 'edit.detachNode' : 'edit.removeNode'),
            action: () => {
              const a = anchor();
              if (!a) return;
              const detaching = stillUsed();
              void props.core.execute(
                (f) => props.core.edit.removeAttached(f, a.parent, a.pred, t0()),
                { group: true },
              )
                .then((ok) => {
                  if (ok) showToast(detaching ? 'edit.nodeDetached' : 'edit.nodeRemoved');
                })
                .catch(() => {});
            },
            term: t0(),
            blocked: detachedQuads(),
            notApplicable: text('edit.removeNoLink'),
            unlockable: true,
          })}
        />
      )}
    </Show>
  );
}

export function RuleDutyGhost(props: { core: Core; ctx: RuleHookCtx }): JSX.Element {
  const term = createMemo(() => (props.ctx.derived ? null : termOf(props.ctx.rule)));
  const option = (): GhostOption => {
    const t0 = term();
    const state = editState(props.core, {
      allow: props.core.editable(t0),
      title: text('edit.dutyOnRule'),
      action: () => {
        let fresh: unknown = null;
        void props.core.execute((f) => { fresh = props.core.edit.addDuty(f, t0, DUTY); },
          { group: true })
          .then((ok) => { if (ok) requestFocusOn(fresh); })
          .catch(() => {});
      },
      term: t0,
      unlockable: true,
    });
    return {
      node: <GhostBadge kind="duty" word={text('edit.duty')} />,
      cls: 'regel-plicht-plus',
      title: state.title,
      on: state.on,
      action: state.action,
    };
  };
  return (
    <Show when={term()}>
      <GhostWithBox cls="ghost-op-rij" options={[option()]} />
    </Show>
  );
}

export function ConstraintStrip(props: { core: Core; ctx: ConstraintHookCtx }): JSX.Element {
  const c = () => props.ctx.c as ConstraintShape | null;
  const ruleTerm = createMemo(() => termOf(props.ctx.rule));
  const term = createMemo(() => (c()?.purposeBinding
    ? purposeBindingTerm(props.core.graph(), ruleTerm())
    : termOf(props.ctx.c)));
  const anchor = createMemo(() => constraintAnchor(props.core.graph(), term(), ruleTerm()));
  const detachedQuads = createMemo(() => detachQuads(
    props.core.graph(), anchor(), term(),
    (s, t) => props.core.edit.closureQuads(s, t),
  ));
  const canDetach = () => detachedQuads().length > 0
    && props.core.quadsInEditSource(detachedQuads());
  const constraintStillUsed = () => staysInUse(props.core.graph(), anchor(), term());
  const derivedReason = () => text('edit.rowDerived');
  const dragItem = createMemo<DragItem | null>(() => {
    const t0 = term(); const a = anchor(); const r = ruleTerm();
    if (!t0) return null;
    return {
      kind: DRAGITEM.CONSTRAINT,
      term: t0,
      parent: r,
      pred: a && a.pred.endsWith('refinement') ? 'refinement' : 'constraint',
      label: (props.ctx.c as { label?: string | null } | null)?.label || undefined,
    };
  });
  const kind = createMemo(() => rowKind(c()));
  const naReason = () => {
    if (kind() === 'slots') return text('edit.slotsNa');
    if (kind() === 'anker') return text('edit.anchorRowNa');
    return text('edit.groupRowNa');
  };
  const canEditSlots = () => kind() === 'slots'
    && slotsEditable(props.core.graph(), term(), props.core);
  const [editorOpen, setEditorOpen] = createSignal(false);
  const [focusField, setFocusField] = createSignal<'left' | 'value' | null>(null);
  createEffect(on(editFocus, (address) => {
    if (!address || !term() || focusAddress(term()) !== address) return;
    if (!canEditSlots()) return;
    setFocusField(slotValues(props.core.graph(), term(), curie as never).left
      ? 'value' : 'left');
    setEditorOpen(true);
  }));
  const rowEditState = (): IconState => editState(props.core, {
    allow: canEditSlots(),
    title: text('edit.editConstraint'),
    action: () => {
      setFocusField(null);
      setEditorOpen((v) => !v);
    },
    term: kind() === 'slots' ? term() : null,
    notApplicable: naReason(),
    unlockable: true,
  });
  return (
    <Show
      when={term()}
      fallback={<DerivedStrip reason={derivedReason()} />}
    >
      {(t0) => (
        <>
        <ActionStrip
          label={text('edit.stripLabel')}
          voor={<SharedMarker term={t0()} card={props.ctx.scope ?? null} />}
          drag={dragItem() && anchor()
            ? dragHandle(dragItem()!)
            : noHandle(text('edit.dragNoLink'))}
          edit={rowEditState()}
          remove={editState(props.core, {
            allow: canDetach(),
            title: text(constraintStillUsed() ? 'edit.detachNode'
              : 'edit.removeConstraint'),
            action: () => {
              const a = anchor();
              if (!a) return;
              const detaching = constraintStillUsed();
              void props.core.execute(
                (f) => props.core.edit.removeAttached(f, a.parent, a.pred, t0()),
                { group: true },
              )
                .then((ok) => {
                  if (ok) showToast(detaching ? 'edit.nodeDetached' : 'edit.constraintRemoved');
                })
                .catch(() => {});
            },
            term: t0(),
            blocked: detachedQuads(),
            notApplicable: text('edit.removeNoLink'),
            unlockable: true,
          })}
        />
        <span class="c-editor-doos">
          <Show when={editorOpen()}>
            <SlotEditor
              core={props.core}
              term={t0()}
              c={c()}
              focus={focusField()}
              onOpened={() => clearFocusFor(focusAddress(t0()))}
              onClose={() => { setEditorOpen(false); setFocusField(null); }}
            />
          </Show>
        </span>
        </>
      )}
    </Show>
  );
}

let constraintCache: { g: unknown; v: number; list: {
  iri: string; curie: string | null; label: string; provenance: string[];
}[] } | null = null;

function constraintCandidates(core: Core, holder: unknown, pred: string): IriOption[] {
  const g = core.graph();
  const v = graphVersion();
  if (!g || !holder) return [];
  if (!constraintCache || constraintCache.g !== g || constraintCache.v !== v) {
    constraintCache = { g, v, list: core.edit.constraintOptions(g) };
  }
  return asIriOptions(constraintCache.list
    .filter((c) => core.edit.attachConstraintCheck(g, holder, pred, c.iri).ok));
}

function ConstraintReuseRow(props: {
  core: Core; holder: unknown; pred: string; options: IriOption[]; onClose: () => void;
}): JSX.Element {
  const pick = (iri: string): void => {
    const verdict = props.core.edit.attachConstraintCheck(
      props.core.graph(), props.holder, props.pred, iri,
    );
    if (!verdict.ok) {
      setNotice(CONSTRAINT_NOTICE[verdict.reden || ''] || 'edit.invalidIri', { invoer: iri });
      return;
    }
    let fresh: unknown = null;
    void props.core.execute((f) => {
      fresh = props.core.edit.attachConstraint(f, props.holder, props.pred, iri).term;
    }, { group: true })
      .then((ok) => {
        if (!ok) return;
        showToast('edit.constraintAttached');
        props.onClose();
        requestFocusOn(fresh);
      })
      .catch(() => {});
  };
  return (
    <ReuseRow
      options={props.options}
      chooseKey="edit.reuseConstraintChoose"
      onPick={pick}
      onClose={props.onClose}
      cls="hergebruik-voorwaarde-rij"
    />
  );
}

export function ConstraintGhost(props: { core: Core; ctx: RuleHookCtx }): JSX.Element {
  const term = createMemo(() => (props.ctx.derived ? null : termOf(props.ctx.rule)));
  const [reuseOpen, setReuseOpen] = createSignal(false);
  const candidates = createMemo(
    () => constraintCandidates(props.core, term(), `${ODRL}constraint`),
  );
  const option = (): GhostOption => {
    const t0 = term();
    const state = editState(props.core, {
      allow: props.core.editable(t0),
      title: text('edit.addConstraint'),
      action: () => {
        let fresh: unknown = null;
        void props.core.execute((f) => { fresh = props.core.edit.addConstraint(f, t0); },
          { group: true })
          .then((ok) => { if (ok) requestFocusOn(fresh); })
          .catch(() => {});
      },
      term: t0,
      unlockable: true,
    });
    return {
      node: <GhostChips />,
      cls: 'voorwaarde-plus-knop',
      title: state.title,
      on: state.on,
      action: state.action,
    };
  };
  const dim = createMemo(() => {
    const t0 = term();
    if (!t0) return null;
    const r = props.ctx.rule as {
      purpose?: unknown; refinements?: { leftIri?: string | null }[];
    } | null;
    if (!r) return null;
    for (const d of (props.ctx.dims || [])) {
      const has = d.iri === PURPOSE_LEFT
        ? !!r.purpose
        : (r.refinements || []).some((c) => c.leftIri === d.iri);
      if (!has) return d;
    }
    return null;
  });
  const dimOption = (): GhostOption => {
    const t0 = term();
    const d = dim()!;
    const name = d.label || d.curie || d.iri;
    const state = editState(props.core, {
      allow: props.core.editable(t0),
      title: text('edit.addGroupConstraint', { dim: name }),
      action: () => {
        let fresh: unknown = null;
        void props.core.execute((f) => {
          fresh = props.core.edit.addConstraint(f, t0, `${ODRL}refinement`,
            { left: d.iri, operator: `${ODRL}eq`, onAction: true });
        }, { group: true })
          .then((ok) => { if (ok) requestFocusOn(fresh); })
          .catch(() => {});
      },
      term: t0,
      unlockable: true,
    });
    return {
      label: `+ ${name}`,
      cls: 'voorwaarde-dim-plus',
      title: state.title,
      on: state.on,
      action: state.action,
    };
  };
  const reuseOption = (): GhostOption => reuseSegment({
    core: props.core,
    term: term(),
    cls: 'voorwaarde-hergebruik',
    count: candidates().length,
    hint: 'edit.reuseConstraintHint',
    none: 'edit.reuseConstraintNone',
    toggle: () => setReuseOpen((v) => !v),
  });
  const segments = (): GhostOption[] => (dim()
    ? [option(), dimOption(), reuseOption()]
    : [option(), reuseOption()]);
  return (
    <Show when={term()}>
      <li class="voorwaarde-plus">
        <GhostWithBox cls="ghost-voorwaarde" options={segments()} />
        <Show when={reuseOpen()}>
          <ConstraintReuseRow
            core={props.core}
            holder={term()}
            pred={`${ODRL}constraint`}
            options={candidates()}
            onClose={() => setReuseOpen(false)}
          />
        </Show>
      </li>
    </Show>
  );
}

